using namespace candidateBackgroundHost;
static int checks=0;static void check(bool ok,const char*why){++checks;if(!ok)throw std::runtime_error(why);}
static QJsonObject json(QString p){QFile f(p);check(f.open(QIODevice::ReadOnly),"fixture read");return QJsonDocument::fromJson(f.readAll()).object();}
static void sql(QString p,const std::function<void(QSqlDatabase&)>& action){auto name=QUuid::createUuid().toString();{auto db=QSqlDatabase::addDatabase("QSQLITE",name);db.setDatabaseName(p);check(db.open(),"isolated SQL open");action(db);db.close();}QSqlDatabase::removeDatabase(name);}
static void exec(QSqlDatabase&db,QString text){QSqlQuery q(db);check(q.exec(text),qPrintable(q.lastError().text()));}
static void seed(const Paths&p,const QJsonObject&fixture){auto all=fixture["sources"].toObject();sql(p.business,[&](auto&db){exec(db,"CREATE TABLE records(kind TEXT,id TEXT,payload TEXT,PRIMARY KEY(kind,id))");for(auto key:QStringList{"accounts","trades"})for(auto v:all["holdings"].toObject()["data"].toObject()[key].toArray()){QSqlQuery q(db);q.prepare("INSERT INTO records VALUES(?,?,?)");q.addBindValue(key);q.addBindValue(v.toObject()["id"].toString());q.addBindValue(QString::fromUtf8(QJsonDocument(v.toObject()).toJson(QJsonDocument::Compact)));check(q.exec(),"seed business");}});
 sql(p.recent,[&](auto&db){exec(db,"PRAGMA application_id=1381188401");exec(db,"CREATE TABLE recent_entries(id TEXT PRIMARY KEY,payload TEXT NOT NULL)");for(auto v:all["recent"].toObject()["data"].toObject()["rows"].toArray()){QSqlQuery q(db);q.prepare("INSERT INTO recent_entries VALUES(?,?)");q.addBindValue(v.toObject()["id"].toString());q.addBindValue(QString::fromUtf8(QJsonDocument(v.toObject()).toJson(QJsonDocument::Compact)));check(q.exec(),"seed recent");}});
 sql(p.leaders,[&](auto&db){exec(db,"PRAGMA application_id=1397511729");exec(db,"CREATE TABLE config(id INTEGER PRIMARY KEY,revision INTEGER,digest TEXT,payload BLOB)");auto config=all["leaders"].toObject()["data"].toObject();auto raw=QJsonDocument(config).toJson(QJsonDocument::Compact);QSqlQuery q(db);q.prepare("INSERT INTO config VALUES(1,?,?,?)");q.addBindValue(config["revision"].toInt());q.addBindValue(QString::fromLatin1(QCryptographicHash::hash(raw,QCryptographicHash::Sha256).toHex()));q.addBindValue(raw);check(q.exec(),"seed leaders");});}
template<class F>static void rejects(F call,const char*why){bool failed=false;try{call();}catch(const std::exception&){failed=true;}check(failed,why);}
int main(int argc,char**argv){QCoreApplication app(argc,argv);try{check(argc==5,"isolated root,source fixture,v1 fixture,output");QTemporaryDir temp(QString(argv[1])+"/host-XXXXXX");check(temp.isValid(),"isolated directory");Paths paths{temp.path()+"/business.sqlite",temp.path()+"/recent.sqlite",temp.path()+"/leaders.sqlite",temp.path()+"/evidence.sqlite"};auto fixture=json(argv[2]);seed(paths,fixture);auto cut=QDateTime::fromString(fixture["capturedAt"].toString(),Qt::ISODateWithMs);Hooks hooks{[cut]{return cut;},{}};Host host(paths,hooks);check(host.accounts().size()==1,"only ledger choices");QJsonObject stock;for(auto v:json(argv[3])["cases"].toArray()){auto c=v.toObject();if(c.contains("error"))continue;auto rows=c["result"].toObject()["rows"].toArray();if(!rows.isEmpty()&&rows[0].toObject()["rawScore"].isDouble()){stock=c["selected"].toArray()[0].toObject();break;}}stock["id"]="SH:stock:600001";stock["symbol"]="sh600001";QJsonArray selected{stock};
 auto value=host.capture(selected,"stable",{"account-A"});verify(value);auto adapter=value["adapter"].toObject(),bg=adapter["backgrounds"].toObject()["SH:stock:600001"].toObject();check(bg["holdings"].toObject()["status"]=="known"&&bg["recent"].toObject()["status"]=="known"&&bg["leaders"].toObject()["status"]=="known","real SQLite source projection");check(bg["themes"].toObject()["status"]=="unknown","themes not invented");auto technical=localCandidate::evaluate(localCandidate::snapshot(selected,"stable",cut));auto a=technical["rows"].toArray()[0].toObject(),b=value["result"].toObject()["rows"].toArray()[0].toObject();check(a["factors"]==b["factors"]&&b["rawScore"].toInt()==a["rawScore"].toInt()+30,"technical v1 factors preserved plus known30");
 rejects([&]{host.capture(selected,"stable",{});},"explicit account selection required");check(host.head().isEmpty()&&!QFile::exists(paths.evidence),"read-only head does not create store");auto head=host.putDraft(value,"");check(host.head()==head&&host.readDraft(head)==value,"atomic adapter+result draft");auto id=host.save("背景隔离记录",value,cut);check(host.list().size()==1&&host.read(id)["bundle"]==value,"named bundle retained");
 auto next=host.capture(selected,"breakout",{"account-A"});auto newer=host.putDraft(next,head);rejects([&]{host.putDraft(value,head);},"stale CAS cannot overwrite newer draft");check(host.head()==newer,"newer preserved after CAS reject");rejects([&]{host.readDraft(head);},"old draft anchor never redirects");rejects([&]{host.putDraft(value,newer,[]{return true;});},"cancel before write");check(host.head()==newer,"cancel preserves current");bool cancelAtCommit=false;auto rollbackHooks=hooks;rollbackHooks.beforeCommit=[&]{cancelAtCommit=true;};rejects([&]{Host(paths,rollbackHooks).putDraft(value,newer,[&]{return cancelAtCommit;});},"cancel after writes rolls back entire bundle transaction");check(host.head()==newer&&host.readDraft(newer)==next,"commit cancellation preserves previous complete pair");auto unsafe=paths;unsafe.evidence=paths.business;rejects([&]{Host(unsafe,hooks).putDraft(value,"");},"evidence cannot target source database");
 auto bad=value;auto wrong=bad["adapter"].toObject();wrong["inputHash"]="bad";bad["adapter"]=wrong;rejects([&]{verify(bad);},"adapter tamper");auto mismatch=value;mismatch["result"]=next["result"];verify(mismatch); // same background and cut may legitimately use another strategy
 auto changedAdapter=next["adapter"].toObject();auto changedRaw=changedAdapter["input"].toObject();changedRaw["hostPaths"]=QJsonObject{};changedAdapter=localCandidateBackgroundAdapter::freeze(changedRaw);mismatch["adapter"]=changedAdapter;rejects([&]{verify(mismatch);},"independently valid adapter/result must match");
 auto missingPaths=paths;missingPaths.recent=temp.path()+"/absent.sqlite";auto partial=Host(missingPaths,hooks).capture(selected,"stable",{"account-A"});check(partial["adapter"].toObject()["backgrounds"].toObject()["SH:stock:600001"].toObject()["recent"].toObject()["status"]=="unknown"&&!QFile::exists(missingPaths.recent),"missing source unknown never created");
 Hooks changed=hooks;changed.betweenReads=[&]{sql(paths.business,[&](auto&db){exec(db,"UPDATE records SET payload=replace(payload,'账本字段样例','已变更') WHERE kind='accounts'");});};rejects([&]{Host(paths,changed).capture(selected,"stable",{"account-A"});},"changed source rejects entire capture");check(host.read(id)["bundle"]==value,"historical replay unaffected by current sources");
 rejects([&]{host.remove(id,"stale");},"delete CAS");auto savedDigest=host.read(id)["digest"].toString();host.remove(id,savedDigest);check(host.list().isEmpty(),"explicit history removal");Host reopened(paths,hooks);check(reopened.readDraft(newer)==next,"reopen frozen bundle");
 for(auto name:QStringList{"unmarked-empty.sqlite","unmarked-valid.sqlite"}){auto other=paths;other.evidence=temp.path()+"/"+name;if(name.contains("valid"))sql(other.evidence,[&](auto&db){exec(db,"PRAGMA user_version=1");});else {QFile empty(other.evidence);check(empty.open(QIODevice::WriteOnly),"create isolated empty file");}QFile before(other.evidence);check(before.open(QIODevice::ReadOnly),"before preservation read");auto bytes=before.readAll();before.close();rejects([&]{Host(other,hooks).putDraft(value,"");},"existing unmarked file must not be adopted");QFile after(other.evidence);check(after.open(QIODevice::ReadOnly)&&after.readAll()==bytes,"foreign bytes unchanged");}
 QFile out(argv[4]);check(out.open(QIODevice::WriteOnly),"own output");out.write(QJsonDocument(QJsonObject{{"passed",true},{"checks",checks},{"bundle",value},{"scope","Isolated Qt SQLite bridge checks; not production or Android device acceptance"}}).toJson(QJsonDocument::Indented));QTextStream(stdout)<<"PASS Qt host SQLite checks="<<checks<<"\n";return 0;}catch(const std::exception&e){QTextStream(stderr)<<e.what()<<'\n';return 1;}}
